use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn exhausted_transient_retries_return_the_last_error() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &RetryConfig {
            max_attempts: 3,
            base_delay_ms: 7,
            max_delay_ms: 100,
        },
        &mut sleeper,
        || {
            calls += 1;
            Err(RetryError::Transient(format!("attempt {calls}")))
        },
    );

    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![7, 14]);
    assert_eq!(result, Err(RetryError::Transient("attempt 3".into())));
}

#[test]
fn success_on_first_attempt_does_not_sleep() {
    let mut sleeper = FakeSleeper::default();
    let result = run_job(
        &RetryConfig {
            max_attempts: 3,
            base_delay_ms: 10,
            max_delay_ms: 20,
        },
        &mut sleeper,
        || Ok(()),
    );

    assert_eq!(result, Ok(()));
    assert!(sleeper.sleeps.is_empty());
}

